package net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class YVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property y of observed panel ")
  void test_yvo_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> YVO.tryFrom(null));
    Assertions.assertEquals(1, YVO.from(1).getY());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> YVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", YVO.from(1).toString());
  }
}
